class Compressor:
    """PowerSGD with error feedback and warm-start projection matrices.

    Approximates gradient matrices via a single randomized power iteration
    with warm-started right-projection Q. Error feedback accumulates the
    low-rank approximation residual. Rank per layer adapts to matrix
    dimensions and target compression ratio. Small / 1-D tensors (e.g.
    batch-norm, biases) bypass compression to avoid high relative error.
    """

    def __init__(self, compress_ratio=0.01):
        self.compress_ratio = compress_ratio
        self.residuals = {}
        self.q_memory = {}

    def compress(self, tensor, name):
        shape = tensor.shape
        numel = tensor.numel()
        # Skip compression for small or 1D tensors
        if numel < 256 or len(shape) < 2:
            return [tensor.clone().flatten()], (shape, False)
        # Reshape to 2D: (out_features, in_features * spatial_dims)
        matrix = tensor.view(shape[0], -1)
        # Error feedback: add accumulated residual
        if name in self.residuals:
            matrix = matrix + self.residuals[name]
        m, n = matrix.shape
        # Adaptive rank from target compression ratio
        rank = max(2, int(self.compress_ratio * m * n / (m + n)))
        rank = min(rank, min(m, n))
        # Warm-start Q from previous iteration, or random init
        if name in self.q_memory and self.q_memory[name].shape == (n, rank):
            q = self.q_memory[name]
        else:
            q = torch.randn(n, rank, device=tensor.device, dtype=tensor.dtype)
        # Single power iteration: P = orth(M @ Q), Q_new = M^T @ P
        p = matrix @ q
        p, _ = torch.linalg.qr(p)
        q_new = matrix.t() @ p
        # Save Q for warm-start next iteration
        self.q_memory[name] = q_new.clone()
        # Error feedback: store residual
        self.residuals[name] = matrix - p @ q_new.t()
        return [p, q_new], (shape, True)

    def decompress(self, compressed_tensors, ctx):
        shape, is_compressed = ctx
        if not is_compressed:
            return compressed_tensors[0].view(shape)
        p, q_new = compressed_tensors
        return (p @ q_new.t()).view(shape)

class Compressor:
    """PowerSGD with error feedback, warm-start, and enhanced rank.
    Low-rank approximation via 2 power iterations for 2D+ gradients.
    Rank adapts per layer. Error feedback corrects residuals.
    Small/1D tensors bypass compression.
    """

    def __init__(self, compress_ratio=0.01):
        self.compress_ratio = compress_ratio
        self.residuals = {}
        self.q_memory = {}

    def compress(self, tensor, name):
        shape = tensor.shape
        numel = tensor.numel()
        if numel < 256 or len(shape) < 2:
            return [tensor.clone().flatten()], (shape, False)
        matrix = tensor.view(shape[0], -1)
        if name in self.residuals:
            matrix = matrix + self.residuals[name]
        m, n = matrix.shape
        rank = max(4, int(2.0 * self.compress_ratio * m * n / (m + n)))
        rank = min(rank, min(m, n))
        if name in self.q_memory and self.q_memory[name].shape == (n, rank):
            q = self.q_memory[name]
        else:
            q = torch.randn(n, rank, device=tensor.device, dtype=tensor.dtype)
        # Two power iterations for better subspace estimation
        p = matrix @ q
        p, _ = torch.linalg.qr(p)
        q = matrix.t() @ p
        q, _ = torch.linalg.qr(q)
        p = matrix @ q
        p, _ = torch.linalg.qr(p)
        q_new = matrix.t() @ p
        # Save orthogonalized Q for stable warm-start
        q_ws, _ = torch.linalg.qr(q_new)
        self.q_memory[name] = q_ws
        self.residuals[name] = matrix - p @ q_new.t()
        return [p, q_new], (shape, True)

    def decompress(self, compressed_tensors, ctx):
        shape, is_compressed = ctx
        if not is_compressed:
            return compressed_tensors[0].view(shape)
        p, q_new = compressed_tensors
        return (p @ q_new.t()).view(shape)
